 const save=async(e:any)=>{e.preventDefault();setSaving(true);try{const day=today();const counterRef=doc(db,"visitorCounters",day);const next=await runTransaction(db,async(tx)=>{const current=await tx.get(counterRef);if(!current.exists()){tx.set(counterRef,{nextNumber:2,updatedAt:serverTimestamp(),updatedBy:profile.uid});return 1}const n=Number(current.data().nextNumber||1);if(!Number.isInteger(n)||n<1)throw new Error("Visitor serial counter is invalid.");tx.update(counterRef,{nextNumber:n+1,updatedAt:serverTimestamp(),updatedBy:profile.uid});return n});const serialNo=`V-${day.replaceAll("-","")}-${String(next).padStart(3,"0")}`;let photoUrl="";if(f.photo){const rr=ref(storage,"visitorPhotos/"+f.locationId+"/"+crypto.randomUUID()+".jpg");await uploadString(rr,f.photo,"data_url");photoUrl=await getDownloadURL(rr)}const now=new Date();await addDoc(collection(db,"visitors"),{serialNo,date:day,entryDate:day,entryTime:now.toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false,timeZone:"Asia/Kolkata"}),name:f.name,company:f.company,mobile:f.mobile,whomToMeet:f.whomToMeet,purpose:f.purpose,checkInAt:serverTimestamp(),checkOutAt:null,photoUrl,remarks:f.remarks,locationId:f.locationId,securityId:profile.uid,securityName:profile.name,securityPersonId:duty?.securityPersonId||profile.uid,securityPersonName:duty?.securityPersonName||profile.name,securityDeskLocationId:duty?.locationId||f.locationId,createdAt:serverTimestamp(),updatedAt:serverTimestamp()});onClose()}catch(err:any){alert(err.message||"Could not save visitor.")}finally{setSaving(false)}};
